"""FNT-03: Ablation report generated by one command and committed.

`footnote eval retrieval --dataset scifact --ablation` writes `ablation.md`; it
must hold every ablation row, each with R@10, nDCG@10 and p95 latency. The generated report is
copied to the committed `eval/ablation.md` (the README links it).
"""

from __future__ import annotations

import re
import shutil
from typing import Any

from acceptance.evalrun import run_eval_retrieval
from acceptance.harness import write_log
from acceptance.support import ROOT, repo_path, thresholds, write_result

COMMITTED = ROOT / "eval" / "ablation.md"
SHIPPED_CHUNKING = "heading"
LEXICAL_PAIRS = ("any+ts_rank", "any+ts_rank_cd", "all+ts_rank", "websearch+ts_rank")
WEIGHTS = ("1", "0.5", "0.3", "0.2")
RERANKERS = ("int8", "fp32")
RERANK_N = (30, 50)
REFERENCES = ("BEIR BM25", "BEIR BM25+CE")
METRIC_COLUMNS = ("R@10", "nDCG@10", "p95 ms")
_DECORATION = re.compile(r"( \*\*shipped\*\*)?( \(.*\))?$")


def required_rows() -> list[tuple[str, str]]:
    """Ablation rows as (row label, split); labels as `retrieval.Variant.name` and the baselines
    in `retrieval._baselines` write them (the decoration is stripped before matching)."""
    c = SHIPPED_CHUNKING
    rows = [(f"vector [{c}]", "test")]
    rows += [(f"lexical {pair} [{c}]", "test") for pair in LEXICAL_PAIRS]
    rows += [(f"hybrid lexical weight {w} [{c}]", s) for s in ("train", "test") for w in WEIGHTS]
    rows += [
        (f"hybrid+rerank {variant} rerank_n {n} [{c}]", "test")
        for variant in RERANKERS
        for n in RERANK_N
    ]
    rows.append(("hybrid+rerank int8 rerank_n 30 [recursive]", "test"))
    rows += [("bm25s", "test"), ("bm25s + vector RRF", "test")]
    return rows


def _label(cell: str) -> str:
    return _DECORATION.sub("", cell)


def _number(cell: str) -> bool:
    try:
        float(cell)
    except ValueError:
        return False
    return True


def test_acc_fnt03_ablation_report() -> None:
    """The ablation command writes every ablation row with R@10, nDCG@10 and p95; commit it."""
    expected = thresholds("FNT-03")
    run = run_eval_retrieval("fnt03", "--dataset", "scifact", "--ablation")
    write_log("FNT-03.log", run.output)
    text = run.ablation_md.read_text(encoding="utf-8")

    by_key = {(_label(r["Configuration"]), r["Split"]): r for r in run.table}
    missing: list[str] = []
    incomplete: list[str] = []
    for label, split in required_rows():
        row = by_key.get((label, split))
        if row is None:
            missing.append(f"{label} ({split})")
        elif not all(_number(row[col]) for col in METRIC_COLUMNS):
            incomplete.append(f"{label} ({split})")
    missing += [ref for ref in REFERENCES if ref not in text]
    shipped_rows = [r["Configuration"] for r in run.table if "**shipped**" in r["Configuration"]]
    if not shipped_rows:
        missing.append("shipped markers")

    COMMITTED.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(run.ablation_md, COMMITTED)

    measured: dict[str, Any] = {
        "rows_required": len(required_rows()) + len(REFERENCES),
        "rows_in_report": len(run.table),
        "missing": missing,
        "incomplete": incomplete,
        "metrics": expected["metrics"],
        "run_dir": repo_path(run.directory),
        "committed": str(COMMITTED.relative_to(ROOT)),
    }
    passed = not missing and not incomplete and COMMITTED.is_file()
    details = (
        f"missing {missing}; without R@10/nDCG@10/p95 {incomplete}"
        if not passed
        else "every ablation row present with R@10, nDCG@10 and p95"
    )
    write_result("FNT-03", measured, passed, details)
    assert passed, f"FNT-03 failed: {details}"
